{
  "title": "Discussion about expat experiences, job search, and language in Slovakia and Austria",
  "topics": [
    {
      "id": "expat-locations",
      "title": "People living abroad",
      "claims": [
        {
          "text": "@AndriiRaccoon lives in Austria",
          "evidence": [3]
        },
        {
          "text": "walternet134 lives in Poland",
          "evidence": [3]
        },
        {
          "text": "Mafiozja has returned to her native country",
          "evidence": [4]
        },
        {
          "text": "P1 has been living in Slovakia for almost a year",
          "evidence": [43]
        },
        {
          "text": "P3 has been in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "P3 lives with a partner who has lived in Austria for over 10 years",
          "evidence": [60]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Job search strategies and outcomes",
      "claims": [
        {
          "text": "LinkedIn is recommended for finding jobs abroad",
          "evidence": [18]
        },
        {
          "text": "P3 sent around 100 job applications and got 3 interviews",
          "evidence": [21]
        },
        {
          "text": "Interview conversion rate is low (about 3% in this case)",
          "evidence": [21]
        },
        {
          "text": "Most job postings in the region require knowledge of the local language",
          "evidence": [26]
        },
        {
          "text": "Some companies hire candidates with little or no local language skills",
          "evidence": [29]
        },
        {
          "text": "Higher education rarely influences hiring decisions",
          "evidence": [32]
        },
        {
          "text": "P3 accepted a minimal salary because a job was needed by early March",
          "evidence": [39]
        },
        {
          "text": "Salary for the position was higher than a typical fast‑food minimum but still low",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations for work and daily life",
      "claims": [
        {
          "text": "German is the primary language in Austria, but English is also used in some workplaces",
          "evidence": [14, 15]
        },
        {
          "text": "Approximately 95 % of vacancies require local language proficiency",
          "evidence": [26]
        },
        {
          "text": "Employers usually ask for B2 level language proficiency, sometimes B1, and a certificate is often not required",
          "evidence": [46]
        },
        {
          "text": "P1 does not know Slovak language",
          "evidence": [43]
        },
        {
          "text": "P1 works in an English‑language job; neighbors speak Ukrainian",
          "evidence": [44, 45]
        },
        {
          "text": "P3 believes B1 level may be sufficient and can be claimed as B2 on a resume",
          "evidence": [46]
        }
      ]
    },
    {
      "id": "salary",
      "title": "Salary expectations in Europe vs. Ukraine",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, but many positions still offer modest pay",
          "evidence": [35]
        },
        {
          "text": "P3’s salary was higher than the minimum in Ukraine but still close to a low end",
          "evidence": [37]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Who currently lives in Bratislava or elsewhere abroad?",
      "evidence": [1]
    },
    {
      "text": "Is there a simpler technology stack that could be used for work?",
      "evidence": [30]
    }
  ]
}
